<?php
namespace ZinCelestial\Platform\Compliance;use RuntimeException;defined('ABSPATH')||exit;
final class EvidenceRepository{public function __construct(private \wpdb $db,private string $table,private int $site_id){}public function append(string $control,string $type,string $content_hash,int $actor):string{if(!preg_match('/^[a-f0-9]{64}$/',$content_hash))throw new RuntimeException('Invalid evidence digest.');$id=wp_generate_uuid4();$ok=$this->db->insert($this->table,['site_id'=>$this->site_id,'evidence_id'=>$id,'control_id'=>sanitize_key($control),'evidence_type'=>sanitize_key($type),'content_hash'=>$content_hash,'actor_id'=>$actor,'collected_at'=>current_time('mysql',true)],['%d','%s','%s','%s','%s','%d','%s']);if($ok!==1)throw new RuntimeException('Evidence append failed.');return$id;}public function for_control(string $control,int $limit=100):array{$limit=max(1,min(100,$limit));return(array)$this->db->get_results($this->db->prepare("SELECT evidence_id,evidence_type,content_hash,actor_id,collected_at FROM {$this->table} WHERE site_id=%d AND control_id=%s ORDER BY collected_at DESC LIMIT %d",$this->site_id,sanitize_key($control),$limit),ARRAY_A);}}
